using ModelContextProtocol.Server;
using System.ComponentModel;
using System.Text.Json;

namespace McpServer.Tools;

/// <summary>
/// MCP tools that wrap a weather REST API.
/// The class is instantiated per-call by the MCP SDK via DI,
/// so constructor-injected services (like HttpClient) just work.
/// </summary>
[McpServerToolType]
public class WeatherTools
{
    private readonly HttpClient _http;

    // HttpClient is injected by the DI container via IHttpClientFactory.
    // The SDK creates a new WeatherTools instance for each tool invocation,
    // resolving constructor parameters from the DI container automatically.
    public WeatherTools(HttpClient http)
    {
        _http = http;
    }

    [McpServerTool, Description("Get current weather for a city.")]
    public async Task<string> GetCurrentWeather(
        [Description("City name, e.g. 'Seattle'")] string city,
        [Description("Unit system: 'metric' or 'imperial'")] string units = "metric")
    {
        var url = $"https://api.weatherapi.com/v1/current.json?q={Uri.EscapeDataString(city)}&units={units}";

        var response = await _http.GetAsync(url);
        response.EnsureSuccessStatusCode();

        var json = await response.Content.ReadAsStringAsync();
        using var doc = JsonDocument.Parse(json);

        var current = doc.RootElement.GetProperty("current");
        var tempC = current.GetProperty("temp_c").GetDouble();
        var condition = current.GetProperty("condition").GetProperty("text").GetString();

        return $"Weather in {city}: {tempC}°C, {condition}";
    }

    [McpServerTool, Description("Get a multi-day weather forecast for a city.")]
    public async Task<string> GetForecast(
        [Description("City name")] string city,
        [Description("Number of forecast days (1-10)")] int days = 3)
    {
        var url = $"https://api.weatherapi.com/v1/forecast.json?q={Uri.EscapeDataString(city)}&days={days}";

        var response = await _http.GetAsync(url);
        response.EnsureSuccessStatusCode();

        var json = await response.Content.ReadAsStringAsync();
        using var doc = JsonDocument.Parse(json);

        var forecastDays = doc.RootElement
            .GetProperty("forecast")
            .GetProperty("forecastday");

        var lines = new List<string> { $"Forecast for {city}:" };
        foreach (var day in forecastDays.EnumerateArray())
        {
            var date = day.GetProperty("date").GetString();
            var maxTemp = day.GetProperty("day").GetProperty("maxtemp_c").GetDouble();
            var minTemp = day.GetProperty("day").GetProperty("mintemp_c").GetDouble();
            var cond = day.GetProperty("day").GetProperty("condition").GetProperty("text").GetString();
            lines.Add($"  {date}: {minTemp}°C – {maxTemp}°C, {cond}");
        }

        return string.Join("\n", lines);
    }
}

